            # We can apply the operation a times where 0 <= a <= y
            # For each a, compute the result

            if t == 1:
                # Type 1: k := ceil(k + x) applied a times
                # After a times: ceil(k + a*x)
                # But since we apply ceil at each step, it's ceil(ceil(...ceil(k+x)+x)...)
                # For integer k, ceil(k + x) = k + ceil(x)
                # Actually, ceil(ceil(k+x)+x) = ceil(k + 2x)
                # So after a times: ceil(k + a*x)

                if x > 0:
                    # Compute ceil(k + a*x) for a in [0, y]
                    # But we want to limit to reachable values up to m
                    for a in range(min(y + 1, m + 2)):  # reasonable limit
                        val = ceil(k + a * x)
                        if val <= m:
                            new_reachable.add(val)
            else:
                # Type 2: k := ceil(k * x) applied a times
                # After a times: ceil(k * x^a)
                if x > 0:
                    for a in range(min(y + 1, m + 2)):
                        val = k * (x ** a)
                        val = ceil(val)
                        if val <= m:
                            new_reachable.add(val)

        # Update reachable set and record all values reached at this step
        for val in new_reachable:
            if ans[val] == -1:
                ans[val] = i + 1

        reachable = new_reachable

    # Output results
    return ' '.join(str(ans[i]) for i in range(1, m + 1)) + '\n'


