import sys
from typing import List, Optional

def parse_input(input_str: str) -> tuple:
    """Parse input string and return N and cost matrix."""
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Fill cost matrix with zeros (N x N, 1-indexed conceptually)
    # cost_matrix[i][j] = cost for city i to build rail to city j
    # Using 1-based indexing for cities (1 to N)
    cost_matrix = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        parts = lines[i].split()
        idx = 1  # Start from 1 since we skip A[i,i]
        for val in parts:
            j = idx
            if i == j:
                j += 1  # Skip diagonal
            elif j > n:
                idx -= 1
            cost_matrix[i][j] = int(val)
            idx += 1

    return n, cost_matrix

def is_stable(n: int, cost_matrix: List[List[int]], matching: List[int]) -> bool:
    """
    Check if the current matching is stable.
    matching[i] = j means city i is paired with city j
    """
    for i in range(1, n + 1):
        if matching[i] == -1:
            continue

        for j in range(1, n + 1):
            if i == j or matching[j] == -1 or i == matching[j]:
                continue

            # Both i and j are already paired
            partner_i = matching[i]
            partner_j = matching[j]

            # Check if both prefer each other over their current partners
            if cost_matrix[i][j] < cost_matrix[i][partner_i] and cost_matrix[j][i] < cost_matrix[j][partner_j]:
                return False

    return True

def get_possible_matchings(n: int) -> List[List[int]]:
    """Generate all possible perfect matchings for N cities."""
    if n % 2 != 0:
        return []

    matchings = []
    used = [False] * (n + 1)
    current = [0] * (n + 1)

    def backtrack(city: int):
        if city > n:
            if current[0] == n // 2:
                matchings.append(current[:])
            return

        if current[0] == n // 2:
            return

        if used[city]:
            backtrack(city + 1)
            return

        if current[0] > n // 2 or len([x for x in current[1:] if x != 0]) == n // 2:
            return

        for i in range(city, n + 1):
            if not used[i]:
                used[i] = True
                current[city] = i
                current[len([x for x in current[1:] if x != 0])] = city

                backtrack(city + 1)

                used[i] = False
                current[len([x for x in current[1:] if x != 0])] = 0

    backtrack(1)
    return matchings

def solve_small(n: int, cost_matrix: List[List[int]]) -> Optional[List[int]]:
    """Solve for small N by checking all possible matchings."""
    if n % 2 != 0:
        return [-1]

    # For very small N, generate all possible perfect matchings
    matchings = []

    def generate_matchings(current_match, used):
        if len(current_match) == n // 2:
            matchings.append(current_match)
            return

        for i in range(1, n + 1):
            if not used[i]:
                used[i] = True
                current_match.append(i)
                for j in range(i + 1, n + 1):
                    if not used[j]:
                        used[j] = True
                        current_match.append(j)

                        generate_matchings(current_match, used.copy())
                        current_match.pop()
                        current_match.pop()
                used[i] = False

    generate_matchings([], [False] * (n + 1))

    for matching in matchings:
        match_list = [0] + list(matching)
        match_list[n//2+1:] = [0] * (n - n//2 - 1)
        match_list = [0] * (n + 1)
        for a, b in zip(matching[::2], matching[1::2]):
            match_list[a] = b
            match_list[b] = a

        if is_stable(n, cost_matrix, match_list):
            return [0] + list(match_list)

    return None

def solution(input_str: str):
    """
    Main solution function.
    Returns a string with the pairing or -1 if no stable pairing exists.
    """
    try:
        n, cost_matrix = parse_input(input_str)
    except:
        return "-1"

    if n % 2 != 0:
        return "-1\n" * n

    # For small N, try to find stable matching
    result = solve_small(n, cost_matrix)

    if result is None:
        return "-1\n" * n

    # Format output
    output_lines = []
    for i in range(1, n + 1):
        output_lines.append(str(result[i]))

    return '\n'.join(output_lines) + '\n'

if __name__ == "__main__":
