def is_lucky(n):
    while n > 0:
        digit = n % 10
        if digit != 4 and digit != 7:
            return False
        n //= 10
    return True

def solution(input_str):
    n, m = map(int, input_str.split('\n')[0].split())

    # Read edges
    edges = []
    for line in input_str.split('\n')[1:1+m]:
        if line:
            u, v = map(int, line.split())
            edges.append((u, v))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components
