        if is_lucky(i):
            lucky_numbers.append(i)

    for size in components_sizes:
        new_dp = dp.copy()
        for s in list(dp.keys()):
            new_sum = s + size
            if new_sum not in dp:
                dp[new_sum] = 1
            else:
