def solution(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    transformers = []
    for i in range(1, K + 1):
        parts = [int(x) for x in lines[i].split()]
        transformers.append(parts)

    # dp[i][j] = minimum energy to reach (i, j)
    # Initialize with infinity
    dp = [[float('inf')] * M for _ in range(N)]
    dp[0][0] = 0

    for i in range(N):
        for j in range(M):
            current_time = i + j  # Minimum time to reach (i, j)

            if current_time == 0:
                continue

            # Try coming from above (i-1, j)
            if i > 0 and dp[i-1][j] != float('inf'):
                # Kill transformers that appear at (i, j) at time current_time
                energy = dp[i-1][j] + kill_energy(i, j, current_time, transformers)
                dp[i][j] = min(dp[i][j], energy)

            # Try coming from left (i, j-1)
            if j > 0 and dp[i][j-1] != float('inf'):
                energy = dp[i][j-1] + kill_energy(i, j, current_time, transformers)
                dp[i][j] = min(dp[i][j], energy)

    return str(dp[N-1][M-1])

def kill_energy(x, y, time, transformers):
    total = 0
    killed = set()
    for t_info in transformers:
        tx, ty, d, t_start, e = t_info

        if time < t_start:
            continue

        rel_time = time - t_start
        pattern = rel_time % 4

        if pattern == 0:
            tx_pos, ty_pos = tx, ty
        elif pattern == 1:
            tx_pos, ty_pos = tx + d, ty - d
        elif pattern == 2:
            tx_pos, ty_pos = tx + d, ty
        elif pattern == 3:
            tx_pos, ty_pos = tx, ty + d

        if tx_pos == x and ty_pos == y:
            total += e
    return total

