def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = int(lines[0].split()[0]), int(lines[0].split()[1])
    a = [int(x) for x in lines[1].split()]

    def f(x):
        """Remove all factors of k from x"""
        while x % k == 0:
            x = x // k
        return x

    memo = {}
    found = False
    ops = []

    def dfs(values):
        nonlocal found
        if found:
            return True

        state = tuple(sorted(values))
        if state in memo:
            return memo[state]

        if len(values) == 1:
            memo[state] = (values[0] == 1)
            return values[0] == 1

        for i in range(len(values)):
            for j in range(i + 1, len(values)):
                x, y = values[i], values[j]
                new_val = f(x + y)
                if new_val > 0:
                    new_values = list(values)
                    new_values.pop(i)
                    new_values.pop(j - 1)
                    new_values.append(new_val)

                    if dfs(tuple(sorted(new_values))):
                        memo[state] = True
                        ops.append((x, y))
                        found = True
                        return True

        memo[state] = False
        return False

    if dfs(tuple(sorted(a))):
        ops.reverse()
        result = ["YES"]
        for x, y in ops:
            result.append(f"{x} {y}")
        return "\n".join(result)
    else:
        return "NO"


