    # - A customers bring 50 yuan (add 1 to our 50-yuan notes)
    # - B customers bring 100 yuan (remove 1 from our 50-yuan notes, need to have one)
    # - C customers are VIP (no payment, no change)
    # - At any point, count(A) >= count(B)
    # - Final 50-yuan notes = a - b must be in [l, r]

    # For fixed a, b, c (where a + b + c = n):
    # - Number of valid arrangements of A and B is given by ballot theorem:
    #   If a >= b, valid = C(a+b, b) - C(a+b, b-1) = (a - b + 1)/(a + 1) * C(a + b, b)
    #   If a < b, valid = 0
    # - We can insert c C's into (a + b + 1) positions in C(a + b + c, c) ways

    def nCr_mod_large_p(n, r, p):
        if r < 0 or r > n:
            return 0
        if r == 0 or r == n:
            return 1

        # For large p (up to 2*10^9), we need to be careful
        # Check if p is prime
        def is_prime(x):
            if x < 2:
                return False
            if x == 2:
                return True
            if x % 2 == 0:
                return False
            for i in range(3, int(x**0.5) + 1, 2):
                if x % i == 0:
                    return False
            return True

        if is_prime(p):
            # Use Lucas theorem
            def comb_lucas(n, k, p):
                if k == 0:
                    return 1
                return comb_lucas(n // p, k // p, p) * comb_mod_small(n % p, k % p, p) % p

            def comb_mod_small(n, k, p):
                numerator = 1
                denominator = 1
                for i in range(k):
                    numerator = (numerator * (n - i)) % p
                    denominator = (denominator * (i + 1)) % p
                return (numerator * pow(denominator, p - 2, p)) % p

            return comb_lucas(n, r, p)
        else:
