    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        u, v, w = parts[0], parts[1], parts[2]
        edges.append({'u': u, 'v': v, 'w': w, 'id': i + 1})

    # Function to build adjacency list excluding certain edge indices
    def build_graph(excluded_ids):
        adj = [[] for _ in range(n + 1)]
        for edge in edges:
            if edge['id'] not in excluded_ids:
                adj[edge['u']].append(edge['v'])
                adj[edge['v']].append(edge['u'])
        return adj

    # BFS to check if t is reachable from s
    def can_reach(adj, s, t):
        if s == t:
            return False
        visited = [False] * (n + 1)
        queue = [s]
        visited[s] = True

        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            if u == t:
                return True

            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return False

    # Algorithm
    best_cost = float('inf')
    solution_edges = []
    found_solution = False

    # Check if already disconnected (no edges needed)
    adj_default = build_graph(set())
    if not can_reach(adj_default, s, t):
        return "0\n0\n"

    # Case 1: Remove exactly 1 edge
    for edge in edges:
        cost = edge['w']
        excluded = {edge['id']}
        adj = build_graph(excluded)
        if not can_reach(adj, s, t):
            if cost < best_cost:
                best_cost = cost
                solution_edges = [edge['id']]
                found_solution = True

    # Case 2: Remove exactly 2 edges (only if no single edge works)
    if not found_solution:
        for i, edge1 in enumerate(edges):
            for j, edge2 in enumerate(edges):
                if i >= j:
                    continue

                excluded = {edge1['id'], edge2['id']}
