                if not can_reach(adj, s, t):
                    cost = edge1['w'] + edge2['w']
                    if cost < best_cost:
                        best_cost = cost
                        solution_edges = sorted([edge1['id'], edge2['id']])
                        found_solution = True

    if found_solution:
        best_edges_str = ' '.join(map(str, solution_edges))
        return f"{best_cost}\n1" + ('' + '\n' + best_edges_str if len(solution_edges) == 1 else '\n2\n' + best_edges_str)
    else:
        return "-1"
