        return "NO"

    # Map each value to list of indices in a
    from collections import defaultdict
    val_to_indices = defaultdict(list)
    for i in range(n):
        val_to_indices[a[i]].append(i)

    # Check if all elements of b exist in a
    for val in b:
        if val not in val_to_indices or not val_to_indices[val]:
            return "NO"

    # Check b is strictly increasing (problem says it is, but verify)
    for i in range(1, len(b)):
        if b[i] <= b[i-1]:
            return "NO"

    # Precompute positions for each value in b
    b_indices = [val_to_indices[val] for val in b]

    INF = float('inf')

    # dp[pos] = minimum cost to complete current element of b, ending at position pos
    # Initially empty (before b[0])
    dp = {}
    INF_DP = INF

    for i in range(m):
        b_val = b[i]
        b_indices_i = b_indices[i]

        # new_dp will store costs for matching b[0..i] (i.e., first i+1 elements)
        new_dp = {}

        for prev_pos, prev_cost in dp.items():
            # For each possible position for current b[i]
            for curr_pos in b_indices_i:
                if curr_pos <= prev_pos:
                    continue
                if b_val <= b[i-1]:
                    continue

                # Calculate intermediate deletion cost between prev_pos and curr_pos
                # Elements that would be left-to-right maximums but aren't b[i] must be deleted
                delete_cost = 0
                running_max = a[prev_pos]
                for k in range(prev_pos + 1, curr_pos):
                    if a[k] > running_max:
                        delete_cost += p[k]
                        running_max = a[k]

                total_cost = prev_cost + delete_cost + p[curr_pos]

                if curr_pos not in new_dp or new_dp[curr_pos] > total_cost:
                    new_dp[curr_pos] = total_cost

        # Also consider starting fresh (i=0 case handled by dp being empty initially)
        if i == 0:
            for curr_pos in b_indices_i:
                cost = p[curr_pos]
                if curr_pos not in new_dp or new_dp[curr_pos] > cost:
                    new_dp[curr_pos] = cost

        dp = new_dp
        if not dp:
            return "NO"

    min_cost = min(dp.values())

    return f"YES\n{min_cost}"
