    cells = [(r, c) for r in range(n) for c in range(m)]
    index = {c: i for i, c in enumerate(cells)}

    # closure[i] is a bitmask of cells covered by cell i (including self and neighbors)
    closure = [0] * total
    for i in range(total):
        r, c = cells[i]
        mask = 0
        for nr, nc in [(r, c), (r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
            if 0 <= nr < n and 0 <= nc < m:
                j = index[(nr, nc)]
                mask |= (1 << j)
        closure[i] = mask

    # Get all subsets of cells and check if any forms a dominating set
    def is_dominating(assigned_mask):
        # assigned_mask has 1 at position i if cell i is in dominating set
        covered = 0
        for i in range(total):
            if assigned_mask >> i & 1:
                covered |= closure[i]
        return covered == (1 << total) - 1

    # Try increasing sizes k = 1, 2, ..., total
    best_size = total
    for k in range(1, total + 1):
        found = False

        def generate_combinations(index, remaining, current_mask):
            nonlocal found
            if found:
                return

            if remaining == 0:
                if is_dominating(current_mask):
                    best_size = k
                    found = True
                return

            if index == total:
                return

            for i in range(index, total - remaining + 1):
                # Include cell i
                new_mask = current_mask | (1 << i)

                # Pruning: check if we can possibly still cover everything
                # (This is a simple pruning based on remaining cells we can add)
                if not found:
                    generate_combinations(i + 1, remaining - 1, new_mask)
                else:
                    return

        generate_combinations(0, k, 0)
        if found:
            break

    return best_size

def solution(input_str):
