    used = [False] * (n + 1)
    chains = []

    for i in range(1, n + 1):
        if prev_of[i] == 0 and not used[i]:
            chain = [i]
            curr = i
            while True:
                nxt = next_of[curr]
                if nxt == 0 or nxt in chain or used[nxt]:
                    break
                used[nxt] = True
                chain.append(nxt)
                curr = nxt
            chains.append(chain)
        used[i] = False

    for i in range(1, n + 1):
        if not used[i]:
            chains.append([i])
        used[i] = True

    # Validate internal prerequisites within chains
    for chain in chains:
        for topic in chain:
            pre = prereqs[topic - 1]
            if pre > 0 and pre in chain:
                idx_topic = chain.index(topic)
                idx_pre = chain.index(pre)
                if idx_pre > idx_topic:
                    return "\n0\n"

    # Build component graph
    topic_comp = {}
    for ci, chain in enumerate(chains):
        for topic in chain:
            topic_comp[topic] = ci

    n_comp = len(chains)
    comp_in = [0] * n_comp
    comp_adj = [[] for _ in range(n_comp)]

    for ci in range(n_comp):
        for topic in chains[ci]:
            pre = prereqs[topic - 1]
            if pre > 0 and pre in topic_comp:
                pc = topic_comp[pre]
                if pc == ci:
                    return "\n0\n"
                comp_adj[pc].append(ci)
                comp_in[ci] += 1

    # Topological sort components
    queue = [i for i in range(n_comp) if comp_in[i] == 0]
    order = []

    while queue:
        ci = queue.pop(0)
        order.append(ci)
        for adj in comp_adj[ci]:
            comp_in[adj] -= 1
            if comp_in[adj] == 0:
                queue.append(adj)

    if len(order) != n_comp:
        return "\n0\n"

    # Build result
    result = []
    for ci in order:
        result.extend(chains[ci])

    pos = {v: i for i, v in enumerate(result)}

    # Verify prerequisites and special pairs
    for i in range(1, n + 1):
        pre = prereqs[i - 1]
        if pos[pre] >= pos[i]:
            return "\n0\n"

    for x, y in specific_pairs:
        if pos[y] != pos[x] + 1:
            return "\n0\n"

    return "\n" + " ".join(map(str, result)) + "\n"
