import sys

def count_factors(x):
    """Count factors of 2 and 5 in x"""
    count2 = 0
    count5 = 0
    while x > 0 and x % 2 == 0:
        count2 += 1
        x //= 2
    while x > 0 and x % 5 == 0:
        count5 += 1
        x //= 5
    return count2, count5

def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    matrix = []
    for i in range(1, n + 1):
        row = list(map(int, lines[i].split()))
        matrix.append(row)

    # DP state: for each cell, we store the pair (c2, c5) 
    # But since we want to minimize min(c2, c5), we track pareto-optimal solutions
    # For each cell, we store a list of (c2, c5) pairs that are non-dominating

    # dp[i][j] = list of (c2, c5) that are pareto-optimal
    dp = [[[] for _ in range(n)] for _ in range(n)]

    # Initialize starting cell
    c2, c5 = count_factors(matrix[0][0])
    dp[0][0].append((c2, c5))

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            # Collect all possible (c2, c5) from parent cells
            candidates = []
            if i > 0:
                for (pc2, pc5) in dp[i-1][j]:
                    c2_new = pc2 + count_factors(matrix[i][j])[0]
                    c5_new = pc5 + count_factors(matrix[i][j])[1]
                    candidates.append((c2_new, c5_new))
            if j > 0:
                for (pc2, pc5) in dp[i][j-1]:
                    c2_new = pc2 + count_factors(matrix[i][j])[0]
                    c5_new = pc5 + count_factors(matrix[i][j])[1]
                    candidates.append((c2_new, c5_new))

            if not candidates:
                # Special case: out of bounds but we still need to handle matrix[0][0]
                if i == 0 and j == 0:
                    continue

            # Filter and keep pareto-optimal solutions
            pareto = []
            for (c2_val, c5_val) in candidates:
                is_dominated = False
                for (p_c2, p_c5) in pareto:
                    if p_c2 <= c2_val and p_c5 <= c5_val and (p_c2 < c2_val or p_c5 < c5_val):
                        is_dominated = True
                        break
                if not is_dominated:
                    # Check if this dominates any in pareto
                    to_remove = []
                    for idx, (p_c2, p_c5) in enumerate(pareto):
                        if c2_val <= p_c2 and c5_val <= p_c5 and (c2_val < p_c2 or c5_val < p_c5):
                            to_remove.append(idx)
                    for idx in reversed(to_remove):
                        pareto[idx] = (c2_val, c5_val)
                    else:
                        pareto.append((c2_val, c5_val))

            dp[i][j] = pareto

    # Find minimum trailing zeros at destination
    min_zeros = float('inf')
    best_pairs = []
    for (c2, c5) in dp[n-1][n-1]:
        zeros = min(c2, c5)
        if zeros < min_zeros:
            min_zeros = zeros
            best_pairs = [(c2, c5)]
        elif zeros == min_zeros:
            best_pairs.append((c2, c5))

    # Find the best pair for path reconstruction
    best_c2, best_c5 = best_pairs[0]

    # Backtrack to find the path
    path = []
    i, j = n - 1, n - 1

    while i > 0 or j > 0:
        val = matrix[i][j]
        c2_val, c5_val = count_factors(val)

        # Check if we could come from top
        if i > 0:
            found = False
            for (pc2, pc5) in dp[i-1][j]:
                if (pc2 + c2_val, pc5 + c5_val) in dp[i][j]:
                    # Verify this path actually matches
                    if (best_c2, best_c5) == (pc2 + c2_val, pc5 + c5_val):
                        path.append('D')
                        i -= 1
                        found = True
                        break

        # Check if we could come from left
        if j > 0 and not found:
            found = False
            for (pc2, pc5) in dp[i][j-1]:
                if (pc2 + c2_val, pc5 + c5_val) in dp[i][j]:
                    if (pc2 + c2_val, pc5 + c5_val) == (best_c2, best_c5):
                        path.append('R')
                        j -= 1
                        found = True
                        break

        if not found:
            # If current doesn't match exactly, try the closest
            # Just pick a valid parent
            candidates = []
            if i > 0:
                for (pc2, pc5) in dp[i-1][j]:
                    candidates.append(('D', i-1, j, pc2, pc5))
            if j > 0:
                for (pc2, pc5) in dp[i][j-1]:
                    candidates.append(('R', i, j-1, pc2, pc5))
            # Pick one with matching prefix if possible
            candidates.sort(key=lambda x: abs(x[3] + c2_val - best_c2) + abs(x[4] + c5_val - best_c5))
            best_move, best_i, best_j, best_pc2, best_pc5 = candidates[0]
            path.append(best_move)
            i, j = best_i, best_j
            best_c2, best_c5 = best_pc2, best_pc5

    path.reverse()
    return f"{min_zeros}\n{''.join(path)}"


