def solution(input_str):
    import sys
    from collections import deque
    from collections import defaultdict

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    adj = defaultdict(list)

    for i in range(1, len(lines)):
        if lines[i]:
            u, v = map(int, lines[i].split())
            edges.append((u, v))
            adj[u].append(v)

    # Find SCCs using Tarjan's algorithm
    index_counter = [0]
    stack = []
    lowlink = {}
    index = {}
    on_stack = {}
    sccs = []

    def strongconnect(v):
        index[v] = index_counter[0]
        lowlink[v] = index_counter[0]
        index_counter[0] += 1
        stack.append(v)
        on_stack[v] = True

        for w in adj[v]:
            if w not in index:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif on_stack.get(w, False):
                lowlink[v] = min(lowlink[v], index[w])

        if lowlink[v] == index[v]:
            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == v:
                    break
            sccs.append(scc)

    for v in range(1, n + 1):
        if v not in index:
            strongconnect(v)

    # For each SCC, calculate calls
    # The key insight: within an SCC of size k, we can visit up to 1000 times per vertex
    # Before that, edges arrange to create as few new calls as possible

    total_calls = 0

    for scc in sccs:
        k = len(scc)
        if k == 1:
            total_calls += 1  # Just 1 call for the single vertex
        else:
            # For a cycle of size k, each vertex can be "entered" up to 1000 times
            # The formula observed: (k-1)*999 + 1000 = k*1000 - 999
            total_calls += k * 1000 - (k - 1)

    return str(total_calls)

