Looking at this problem, I need to find a minimal k-covering for each k from 1 to minDegree. A k-covering means selecting a minimum subset of edges such that every vertex has at least k incident edges from the selected subset.

This is a classic bipartite matching/flow problem. I'll use maximum flow to determine which edges form the minimal k-covering.

The solution:
1. For each k from 1 to minDegree, build a flow network where:
   - Source connects to U vertices with capacity k
   - V vertices connect to sink with capacity k  
   - Original edges (U→V) have capacity 1
2. If max flow equals k*(n1+n2), valid k-covering exists
3. Edges carrying flow are part of the minimal k-covering

```python
from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []
        self.ptr = []

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, rev_idx in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow):
        if u == t or flow == 0:
            return flow
        pushed = 0
        for i in range(self.ptr[u], len(self.graph[u])):
            self.ptr[u] = i
            v, cap, rev_idx = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
                pf = self.dfs(v, t, min(flow, cap))
                if pf > 0:
                    self.graph[u][i][1] -= pf
                    self.graph[v][rev_idx][1] += pf
                    pushed += pf
                    flow -= pf
                    if flow == 0:
                        break
        return pushed

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            self.ptr = [0] * self.n
            while True:
                pf = self.dfs(s, t, float('inf'))
                if pf == 0:
                    break
                flow += pf
        return flow


def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    if lines[0]:
        parts = lines[0].split()
        n1 = int(parts[0])
        n2 = int(parts[1])
        m = int(parts[2])

        edges = []
        for i in range(1, len(lines)):
            if lines[i].strip():
                parts = lines[i].split()
                edges.append((int(parts[0]), int(parts[1])))
    else:
        return ""

    deg_u = [0] * (n1 + 1)
    deg_v = [0] * (n2 + 1)
    for u, v in edges:
        deg_u[u] += 1
        deg_v[v] += 1

    min_degree = 0
    if n1 > 0 and n2 > 0:
        min_degree = min(deg_u[1:] + deg_v[1:])

    output = []

    for k in range(1, min_degree + 1):
        if n1 == 0 or n2 == 0:
            output.append("0")
            continue

        dinic = Dinic(n1 + n2 + 2)
        s = 0
        t = n1 + n2 + 1

        for i in range(n1):
            dinic.add_edge(s, i, k)

        for i in range(n2):
            dinic.add_edge(n1 + i, t, k)

        for i in range(m):
            u, v = edges[i]
            dinic.add_edge(u - 1, n1 + v - 1, 1)

        flow = dinic.max_flow(s, t)
        required = k * n2

        cntk = 0
        result = []

        if flow == required:
            for i in range(m):
                u, v = edges[i]
                u_idx = u - 1
                v_idx = n1 + v - 1

                fwd_idx = -1
                for j, e in enumerate(dinic.graph[u_idx]):
                    if e[0] == v_idx:
                        fwd_idx = j
                        break

                if fwd_idx >= 0 and dinic.graph[v_idx][dinic.graph[u_idx][fwd_idx][2]][1] > 0:
                    cntk += 1
                    result.append(i + 1)
        else:
            cntk = 0
            result = []

        if cntk == 0:
            output.append("0")
        else:
            output.append(str(cntk) + " " + " ".join(map(str, sorted(result))))

    return "\n".join(output)


