# Solution based on understanding that f_r(n) has a multiplicative structure
# For n = p1^e1 * p2^e2 * ... * pk^ek, f_r(n) = product of f_r(p_i^e_i) across all prime factors

def solution(argv):
    MOD = 10**9 + 7

    if not argv.strip():
        return ''

    lines = argv.strip().split('\n')
    q = int(lines[0])
    queries = []

    for i in range(1, len(lines)):
        if i < q + 1 or queries >= q:
            parts = lines[i].split()
            if parts:
                r, n = int(parts[0]), int(parts[1])
                queries.append((r, n))

    # Parse max r and n needed
    needed = [None, None]
    for r, n in queries:
        if needed[0] is None or r > needed[0]:
            needed[0] = r + 1
        if needed[1] is None or n > needed[1]:
            needed[1] = n  # For factorization, we need up to sqrt(n) but let's compute primes up to n

    max_val = needed[1] + 1 if needed[1] else 1000001
    max_r = needed[0] + 1 if needed[0] else 1000001

    # Precompute smallest prime factor (SPF) using sieve
    spf = list(range(max_val))
    for i in range(2, int(max_val**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_val, i):
                if spf[j] == j:
                    spf[j] = i

    # Get prime factorization
    def get_prime_factors(n):
        factors = {}
        while n > 1:
            p = spf[n]
            count = 0
            while n % p == 0:
                n //= p
                count += 1
            factors[p] = count
        return factors

    # Precompute contributions for each (exponent, r) pair
    # Based on pattern: f_r(p^e) = (e + r)! / (e! * r!) which is binomial coefficient C(e+r, r)
    # After precomputation of factorials, we can compute C(e+r, r) = (e+r)! * inverse(e!) * inverse(r!)

    max_sum = max_r + needed[1] + 5
    fact = [1] * max_sum
    inv = [1] * max_sum

    for i in range(1, max_sum):
        fact[i] = (fact[i-1] * i) % MOD

    finv = [1] * max_sum
    finv[max_sum - 1] = pow(fact[max_sum - 1], MOD - 2, MOD)

    for i in range(max_sum - 2, -1, -1):
        finv[i] = (finv[i+1] * (i + 1)) % MOD

    def binomial(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * finv[k] % MOD * finv[n - k] % MOD

    def compute_f_r(n, r):
        if n == 1:
            return 1
        factors = get_prime_factors(n)
        result = 1
        for p, e in factors.items():
            # Contribution for p^e with level r
            result = result * binomial(e + r, r) % MOD
        return result

    output_lines = []
    for r, n in queries:
        res = compute_f_r(n, r)
        output_lines.append(str(res))

    return '\n'.join(output_lines)


