# solution.py
def solution(input_data):
    """
    Solve the planet visiting problem.

    Args:
        input_data: String containing n, k, m separated by spaces/newlines
    Returns:
        String containing the answer modulo 10^9 + 7
    """
    n, k, m = map(int, input_data.strip().split())
    MOD = 10**9 + 7

    # Edge case: visiting 1 planet, just choose starting position
    if k == 1:
        return str(n)

    # Edge case: can't visit k planets from n
    if k > n:
        return "0"

    total = 0

    # For each starting planet, count all valid paths of length k
    for start in range(1, n + 1):
        total += dfs(start, k - 1, {start}, n, m, MOD)

    return str(total % MOD)


def dfs(current, remaining, visited, n, m, mod):
    """Backtracking DFS to count valid paths."""
    if remaining == 0:
        return 1

    count = 0
    # Can move to any planet from 1 to current + m
    limit = min(n, current + m)
    for nxt in range(1, limit + 1):
        if nxt not in visited:
            visited.add(nxt)
            count += dfs(nxt, remaining - 1, visited, n, m, mod)
            visited.remove(nxt)

    return count % mod
