                    count = (count + dfs(nxt, remaining - 1)) % MOD
                    visited.remove(nxt)

            return count

        total = (total + dfs(start, k - 1)) % MOD

    return str(total)


# Test cases
def test_examples():
    assert solution('3 3 1\n') == '4'
    assert solution('4 2 1\n') == '9'
    assert solution('5 5 4\n') == '120'
    assert solution('100 1 2\n') == '100'

if __name__ == "__main__":
    test_examples()
    print("All tests passed!")
